def repl(s,old,new):
 p=rf'<figure[^>]*data-v188-plate="{re.escape(old)}"[\s\S]*?</figure>';o,n=re.subn(p,new,s,count=1)
 if n!=1: raise SystemExit(f'{old}: {n}');return o
 return o
def main(root):
 ps=[Path(root)/'academic_payload/index.html',Path(root)/'app/src/main/assets/www/index.html']
 for p in ps:
  s=p.read_text(encoding='utf-8');s=repl(s,'pila-external',EXT);s=repl(s,'pila-pallial',PAL);s=repl(s,'pila-digestive',DIG);s=repl(s,'pila-nervous',NER);s=repl(s,'pila-reproductive',REP)
  # New excretory requirement inserted beside digestive; circulatory plate is not touched.
  if DIG not in s: raise SystemExit('Pila insertion anchor missing')
  s=s.replace(DIG,DIG+EXC,1);p.write_text(s,encoding='utf-8')
 if ps[0].read_bytes()!=ps[1].read_bytes(): raise SystemExit('payload copies diverged')
 print('Pila authorized remediation applied; circulatory untouched; BUILD_ELIGIBLE=NO')
if __name__=='__main__':main(sys.argv[1] if len(sys.argv)>1 else '.')